import {createSimulation} from '../../src/game/core/simulation.ts';
import {validateSave,parseSave,serializeSave} from '../../src/game/persistence/save-v1.ts';
import {migrateSaveV1,validateSaveV2,parseSaveV2,serializeSaveV2,legacySimulationState} from '../../src/game/persistence/save-v2.ts';
import {prepareConservationGrant} from '../../src/game/economy/conservation-grant.ts';
import {prepareElephantConstruction} from '../../src/game/economy/elephant-construction.ts';
import {prepareElephantWelcome} from '../../src/game/animals/elephants/residents.ts';
import {totals,compactFinance} from '../../src/game/economy/journal.ts';
import {isMacaw} from '../../src/game/core/species.ts';
import {serviceRealSupplies} from './elephant-economy.ts';
const check=(ok:unknown,message:string)=>{if(!ok)throw Error(message);};
const ordered=(v:unknown):unknown=>Array.isArray(v)?v.map(ordered):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>[k,ordered(x)])):v;
const same=(a:unknown,b:unknown,label:string)=>check(JSON.stringify(ordered(a))===JSON.stringify(ordered(b)),label+' differs');
type Sim=ReturnType<typeof createSimulation>;
function macawService(s:Sim){for(const kind of ['food','water']as const){const v=s[kind+'View' as 'foodView'|'waterView']();if(v.exists&&v.stock<=2)check(s[kind]('refill',v.revision,s.commandRevision()).ok,'Actual macaw service refused');}}
/** Real original quest journey; cold loads/time partitions are compared to an original V1 engine, not hand-written expected quest state. */
export function runLegacyQuestTwin(source:unknown){
 const old=validateSave(source),migrated=migrateSaveV1(source);if(!old.ok||!migrated.ok)throw Error('Invalid new golden source');let a=createSimulation(old.value),b=createSimulation(migrated.value);a.setSpeed(1);b.setSpeed(10);const claims:Array<{id:string;tick:number}>=[],coldLoads:Array<{tick:number;care:boolean;visitor:boolean}>=[];let coldCare=false,coldVisitor=false,comparisons=0;
 function compare(){const x=a.snapshot(),s=b.snapshot();if(x.schemaVersion!==1||s.schemaVersion!==2)throw Error('Wrong twin schema');const y=legacySimulationState(s);y.world.height=10;y.world.tiles=y.world.tiles.slice(0,120);y.preferences.speed=1;same(x,y,'Original V1 versus migrated full legacy snapshot');comparisons++;}
 try{
  for(const s of [a,b]){check(s.buildHabitat({x:4,z:4},'habitat-legacy-regression',s.commandRevision()).ok,'Actual legacy habitat refused');for(const cell of [{x:1,z:7},{x:2,z:7},{x:3,z:7},{x:3,z:6},{x:3,z:5}])check(s.buildPath(cell,s.commandRevision()).ok,'Actual legacy path refused');check(s.claimMission({id:'Q01',command:s.commandRevision()}).ok,'Actual Q01claim refused');for(const kind of ['food','water','perch']as const)check(s[kind]('place',0,s.commandRevision()).ok,'Actual legacy care placement refused');for(const kind of ['food','water']as const){const view=s[kind+'View' as 'foodView'|'waterView']();check(s[kind]('refill',view.revision,s.commandRevision()).ok,'Actual legacy initial service refused');}check(s.birds('welcome'),'Actual legacy welcome refused');check(s.visitors(true),'Actual legacy entrance refused');}
  claims.push({id:'Q01',tick:a.snapshot().tick});compare();
  for(let i=0;i<6000&&a.snapshot().missions.completedIds.length<4;i++){
   for(const s of [a,b])macawService(s);const view=a.missionView(),current=view.rows.find(r=>r.id===view.currentId);if(current?.status==='ready'){check(b.missionView().rows.find(r=>r.id===current.id)?.status==='ready','Migrated quest readiness differs');for(const s of [a,b])check(s.claimMission({id:current.id,command:s.commandRevision()}).ok,'Actual original quest claim refused');claims.push({id:current.id,tick:a.snapshot().tick});compare();}
   if(a.snapshot().missions.completedIds.length===4)break;a.advance(100);b.advance(10);const x=a.snapshot(),care=x.missions.objectives.comfortableTicks,visitor=x.visitors.some(v=>v.entry?.status==='paid'&&v.journey&&!v.journey.viewed);
   if(!coldCare&&care>=12&&care<50||!coldVisitor&&visitor){coldLoads.push({tick:x.tick,care:!coldCare&&care>=12&&care<50,visitor:!coldVisitor&&visitor});coldCare||=care>=12&&care<50;coldVisitor||=visitor;const y=b.snapshot();if(x.schemaVersion!==1||y.schemaVersion!==2)throw Error('Wrong cold twin schema');const ca=parseSave(serializeSave(x)),cb=parseSaveV2(serializeSaveV2(y));if(!ca.ok||!cb.ok)throw Error('Golden twin cold parse failed');a.dispose();b.dispose();a=createSimulation(ca.value);b=createSimulation(cb.value);for(const s of [a,b]){s.setPaused(true);const before=s.snapshot();s.advance(86400000);same(s.snapshot(),before,'Paused twin');s.setPaused(false);}compare();}
   if(i%25===0)compare();
  }
  compare();const legacy=a.snapshot(),expanded=b.snapshot();if(legacy.schemaVersion!==1||expanded.schemaVersion!==2)throw Error('Wrong completed twin schema');check(legacy.missions.completedIds.length===4&&coldCare&&coldVisitor,'Incomplete original quest/cold journey');check(a.missionView().rewards===60&&b.missionView().rewards===60,'Original60ZCrewards changed');check(expanded.elephantGrove.grant===null&&expanded.animals.length===2,'Migration auto-unlocked elephants or grant');return{legacy,expanded,claims,coldCare,coldVisitor,coldLoads,comparisons};
 }finally{a.dispose();b.dispose();}
}
/** Mixed post-Q04reference. Extra financial command generations, attraction/visitors and two-habitat upkeep intentionally differ; macaw FSM/stock/legacy proofs must not. */
export function runMixedLegacyTrace(source:unknown,ticks=6000){
 const old=validateSave(source),migrated=migrateSaveV1(source);if(!old.ok||!migrated.ok)throw Error('Invalid claimed-Q04source');const grant=prepareConservationGrant(migrated.value,{command:migrated.value.economy.nextCommand});if(!grant.ok)throw Error('Actual grant candidate refused');const built=prepareElephantConstruction(grant.state,{x:3,z:11},'habitat-mixed-regression',grant.state.economy.nextCommand);if(!built.ok)throw Error('Actual mixed Grove refused');const welcomed=prepareElephantWelcome(built.state,built.state.economy.nextCommand);if(!welcomed.ok)throw Error('Actual mixed welcome refused');let a=createSimulation(old.value),b=createSimulation(welcomed.state);const originalMissions=structuredClone(old.value.missions),admitted:Array<{id:string;amount:number}>=[],viewed:Array<{id:string;habitat:string}>=[];let comparisons=0,coldLoads=0;
 function watch(){b.subscribe(e=>{if(e.type==='visitor-admitted')admitted.push({id:e.admissionId,amount:e.amount});if(e.type==='visitor-viewed')viewed.push({id:e.visitorId,habitat:e.habitatId});});}
 function compare(){const x=a.snapshot(),y=b.snapshot();for(const key of ['tick','gameTimeMs','randomState']as const)same(x[key],y[key],'Mixed one-clock/RNG '+key);same(x.animals,y.animals.filter(isMacaw),'Full original macaw FSM/needs/motion/counters');same(x.missions,originalMissions,'Original reference quest proof');same(y.missions,originalMissions,'Mixed legacy quest proof');const resource=(s:typeof x)=>s.world.resources.filter(r=>r.kind==='food'||r.kind==='water'||r.kind==='perch').map(r=>{const{revision,...value}=r;void revision;return value;});same(resource(x),resource(y),'Actual original macaw resource identity/stock/ports');comparisons++;}
 try{
  for(const s of [a,b]){s.setSpeed(1);s.visitors(false);}for(const kind of ['elephant-browse','elephant-browse','elephant-water','elephant-pond','elephant-shade','elephant-log']as const){const cell=b.defaultElephantCareCell(kind);check(cell&&b.placeElephantCare({command:b.commandRevision(),kind,cell}).ok,'Actual mixed care placement refused');}for(const r of b.elephantCareSnapshot().resources.filter(r=>r.capacity===8))check(b.refillElephantCare({command:b.commandRevision(),id:r.id,revision:r.revision}).ok,'Actual mixed initial service refused');for(const cell of [{x:1,z:9},{x:1,z:10},{x:2,z:10},{x:2,z:11},{x:2,z:12},{x:2,z:13}])check(b.buildPath(cell,b.commandRevision()).ok,'Actual mixed connector refused');for(let i=0;i<2500&&(a.visitorView().active||b.visitorView().active);i++){a.advance(100);b.advance(100);compare();}check(!a.visitorView().active&&!b.visitorView().active,'Original visitors not safely drained');compare();const baseAdmissions=totals(b.snapshot()).counts.ticket;watch();a.visitors(true);b.visitors(true);b.setSpeed(10);
  for(let i=0;i<ticks;i++){
   if(i%10===0){macawService(a);serviceRealSupplies(b);}const eh=b.elephantMissionView(),row=eh.rows.find(r=>r.id===eh.currentId);if(row?.status==='ready'){const quote={id:row.id,command:b.commandRevision()},candidate=b.prepareElephantMission(quote);check(candidate.ok&&b.acceptCommittedElephantMission(candidate.state,quote),'Mixed core accepted-candidate fixture failed');}
   a.advance(100);b.advance(10);compare();if(i===Math.floor(ticks/2)){const x=a.snapshot(),y=b.snapshot();if(x.schemaVersion!==1||y.schemaVersion!==2)throw Error('Wrong mixed checkpoint schema');check(compactFinance(x,[],true)&&compactFinance(y,[],true),'Mixed retention fold refused');const ca=parseSave(serializeSave(x)),cb=parseSaveV2(serializeSaveV2(y));if(!ca.ok||!cb.ok)throw Error('Mixed cold parse failed');a.dispose();b.dispose();a=createSimulation(ca.value);b=createSimulation(cb.value);watch();coldLoads++;compare();}
  }
  const legacy=a.snapshot(),mixed=b.snapshot();if(legacy.schemaVersion!==1||mixed.schemaVersion!==2)throw Error('Wrong mixed final schema');check(validateSave(legacy).ok&&validateSaveV2(mixed).ok,'Mixed final validation failed');check(admitted.length===totals(mixed).counts.ticket-baseAdmissions&&admitted.every(a=>a.amount===10)&&new Set(admitted.map(a=>a.id)).size===admitted.length,'Mixed ticket event or price duplicated');check(new Set(viewed.map(v=>v.habitat)).size===2,'Actual mixed visits did not see both habitats');check(a.missionView().rewards===60&&b.missionView().rewards===60,'Mixed legacy reward display changed');return{legacy,mixed,ticks,comparisons,coldLoads,admitted,viewed};
 }finally{a.dispose();b.dispose();}
}
